using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class B1InteriorInspect {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static string HP(Transform t)=>t.parent?HP(t.parent)+"/"+t.name:t.name;
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");var root=GameObject.Find("B1_ResearchAndStaffFloor");var ts=root.GetComponentsInChildren<Transform>(true);var info=new{scene=s.path,root=V(root.transform.position),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=HP(l.transform),parent=HP(l.transform.parent),pos=V(l.transform.localPosition),world=V(l.transform.position),type=l.type.ToString(),l.intensity,l.range}),colliders=ts.SelectMany(t=>t.GetComponents<Collider>()).Select(c=>new{path=HP(c.transform),type=c.GetType().Name,center=V(c.bounds.center),size=V(c.bounds.size)}),protectedTransforms=ts.Where(t=>!HP(t).Contains("/Equipment/")&&!HP(t).Contains("/Lighting/")).Select(t=>new{path=HP(t),pos=V(t.localPosition),rot=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf})};File.WriteAllText(R+"/SourceAssets/B1_InteriorRedesign/before_scene.json",JsonConvert.SerializeObject(info,Formatting.Indented));return new{scene=s.path,objects=ts.Length,lights=root.GetComponentsInChildren<Light>().Length,lightingExample=info.lights.Take(3)};}
}
